const thunderWolfSheet=new Image();thunderWolfSheet.assetSrc='assets/thunder-wolf-v1.png';
function thunderWolfLane(point,start,end,width){let dx=end.x-start.x,dy=end.y-start.y,length=Math.hypot(dx,dy);if(length<.01)return false;let along=((point.x-start.x)*dx+(point.y-start.y)*dy)/length,side=Math.abs((point.x-start.x)*dy-(point.y-start.y)*dx)/length;return along>=-1e-8&&along<=length+1e-8&&side<=width+1e-8;}
function beginThunderWolf(e){let angle=Math.atan2(p.y-e.y,p.x-e.x),origin={x:e.x,y:e.y},target={...origin};for(let s=6;s<=360;s+=6){let q={x:origin.x+Math.cos(angle)*s,y:origin.y+Math.sin(angle)*s};if(!passable(q.x,q.y,18)||!lineClear(target,q,18))break;target=q;}e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'thunderTrailRush',bespoke:true,windup:.9,origin,target,last:{...origin},blocked:false,dashHit:false,waves:0};e.facing=Math.cos(angle)-Math.sin(angle)<0?-1:1;}
const thunderWolfAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r6e0')return thunderWolfAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='thunderTrailRush'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=340&&clear){beginThunderWolf(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.6;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,130*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.last)>24){e.attack=null;e.state='idle';e.t=1.5;return;}
 e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(e.elapsed>=.9&&!a.blocked){let t=e.elapsed>=1.3?1:Math.max(0,(e.elapsed-.9)/.4),q={x:a.origin.x+(a.target.x-a.origin.x)*t,y:a.origin.y+(a.target.y-a.origin.y)*t},dx=q.x-e.x,dy=q.y-e.y,n=Math.max(1,Math.ceil(Math.hypot(dx,dy)/6)),from={x:e.x,y:e.y};for(let i=0;i<n;i++){let x=e.x+dx/n,y=e.y+dy/n;if(!passable(x,y,18)||!lineClear(e,{x,y},18)){a.blocked=true;break;}e.x=x;e.y=y;}a.last={x:e.x,y:e.y};if(!a.dashHit&&thunderWolfLane(p,from,a.last,32)&&lineClear(e,p)){a.dashHit=true;hurt(56);}}
 while(a.waves<3&&e.elapsed>=Math.round((1.7+a.waves*.6)*1e6)/1e6){a.waves++;e.struck=true;if(thunderWolfLane(p,a.origin,a.last,26)&&lineClear(a.origin,p)&&lineClear(a.last,p))hurt(24);playSound('impact',e.x,e.y);}
 if(e.elapsed>=3.4){e.attack=null;e.state='idle';e.t=2.4;}
};
function paintThunderWolfLane(a,fired,width=26){let end=a.last,dx=end.x-a.origin.x,dy=end.y-a.origin.y,len=Math.hypot(dx,dy);if(len<.01)return;let nx=-dy/len*width,ny=dx/len*width,points=[{x:a.origin.x+nx,y:a.origin.y+ny},{x:end.x+nx,y:end.y+ny},{x:end.x-nx,y:end.y-ny},{x:a.origin.x-nx,y:a.origin.y-ny}];ctx.save();ctx.fillStyle=fired?'#fff3aa88':'#e3ba442a';ctx.strokeStyle=fired?'#fffbe4':'#e5c867';ctx.lineWidth=fired?3:1;ctx.beginPath();points.forEach((p,i)=>{let q=project(p.x,p.y);if(i)ctx.lineTo(q.x,q.y);else ctx.moveTo(q.x,q.y);});ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();}
const thunderWolfGroundBase=drawGroundEffects;drawGroundEffects=()=>{thunderWolfGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r6e0'):enemies)){let a=e.attack;if(e.species!=='r6e0'||e.hp<=0||a?.pattern!=='thunderTrailRush')continue;if(!visibleAt(e.x,e.y)&&!visibleAt(a.origin.x,a.origin.y))continue;if(e.elapsed<.9)paintThunderWolfLane({...a,last:a.target},false,32);else paintThunderWolfLane(a,a.waves>0&&e.elapsed<1.7+(a.waves-1)*.6+.16);}};
const thunderWolfDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{
 if(e.species!=='r6e0'||!thunderWolfSheet.complete||!thunderWolfSheet.naturalWidth||!thunderWolfSheet.naturalHeight)return thunderWolfDrawBase(e,size);
 let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='thunderTrailRush')f={row:2,col:e.elapsed<.45?0:e.elapsed<.9?1:e.elapsed<1.3?2:3};let q=project(e.x,e.y),sw=thunderWolfSheet.naturalWidth/4,sh=thunderWolfSheet.naturalHeight/3,w=235,h=w*sh/sw,anchor=[.84,.75,.72][f.row];
 ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,thunderWolfSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(thunderWolfSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;
};
const thunderWolfSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r6e0'?140:thunderWolfSizeBase(e);
